<script setup lang="ts">import{ref,watch}from'vue';import{Search,FileText,LayoutDashboard}from'lucide-vue-next';import{backend}from'../services/backend';import type{SearchResult}from'../types';const p=defineProps<{open:boolean}>();const emit=defineEmits<{close:[],pick:[SearchResult]}>();const q=ref(''),results=ref<SearchResult[]>([]);let timer:any;watch(q,()=>{clearTimeout(timer);timer=setTimeout(async()=>results.value=q.value?await backend.search(q.value):[],120)});</script>
<template><div v-if="open" class="modal-shade" @pointerdown.self="emit('close')"><section class="search-modal"><div class="search-input"><Search/><input autofocus v-model="q" placeholder="搜索画布、文字、文件、链接…" @keydown.esc="emit('close')"></div><div class="search-results"><button v-for="r in results" :key="r.kind+r.id" @click="emit('pick',r)"><LayoutDashboard v-if="r.kind==='canvas'"/><FileText v-else/><span><b>{{r.title}}</b><small>{{r.subtitle}}</small></span></button><p v-if="q&&!results.length">没有找到相关内容</p><p v-if="!q">输入关键词，瞬间定位任何内容</p></div></section></div></template>
